import type { Resources } from './experiment'

/** Crisis event types the GM can generate */
export type CrisisEventType = 'resource' | 'structural' | 'social' | 'environmental' | 'discovery' | 'meta'

/** Severity levels for crisis events */
export type CrisisSeverity = 'low' | 'medium' | 'high' | 'critical'

/** A crisis event generated by the GM */
export interface CrisisEvent {
  type: CrisisEventType
  description: string
  affects?: string[]
  severity: CrisisSeverity
}

/** GM's plan for a round (matches shared/schemas/gm_plan.json) */
export interface GMPlan {
  round: number
  roundTheme: string
  reasoning: string
  crisisEvent: CrisisEvent
  resourceModifiers: Partial<Resources>
  environmental?: string
  narration: string
  metaHint: string | null
}
